-- Seed additional spells for D&D 5e, Tormenta 20, and Pathfinder 2e
delete from public.spells where (system = 'tormenta20' or system = 'pathfinder') and user_id is null;

insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values

-- D&D 5e (Adicionais)
(null, 'dnd5e', 'Bênção', 1, 'Encantamento', '1 ação', '9 metros', 'V, S, M (um borrifo de água benta)', 'Concentração, até 1 minuto', 'Você abençoa até três criaturas de sua escolha dentro do alcance. Sempre que um alvo realizar uma jogada de ataque ou teste de resistência antes da magia acabar, o alvo pode rolar um d4 e somar o resultado obtido.', false),
(null, 'dnd5e', 'Luz', 0, 'Evocação', '1 ação', 'Toque', 'V, M (um vaga-lume ou fósforo)', '1 hora', 'Você toca um objeto que não meça mais de 3 metros em qualquer dimensão. Até a magia acabar, o objeto emite luz brilhante em um raio de 6 metros e luz plena por mais 6 metros adicionais. A luz pode ser colorida.', false),
(null, 'dnd5e', 'Santuário', 1, 'Abjuração', '1 ação bônus', '9 metros', 'V, S, M (um pequeno espelho de prata)', '1 minuto', 'Você protege uma criatura dentro do alcance. Qualquer criatura que tentar atacar ou conjurar uma magia nociva contra o alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, deve escolher um novo alvo ou perder o ataque/magia.', false),
(null, 'dnd5e', 'Queda Suave', 1, 'Transmutação', '1 reação (ao cair)', '18 metros', 'V, M (uma pena ou penugem)', '1 minuto', 'Escolha até cinco criaturas caindo dentro do alcance. A velocidade de queda dos alvos é reduzida para 3 metros por rodada até a magia acabar. Se o alvo pousar antes da magia acabar, não sofre dano de queda.', false),
(null, 'dnd5e', 'Identificar', 1, 'Adivinhação', '1 minuto', 'Toque', 'V, S, M (uma pérola de 100 PO)', 'Instantânea', 'Você toca um objeto mágico. Você aprende as suas propriedades, como usá-las, se requer sintonia, e quantas cargas ele tem. Se conjurado sobre uma criatura, você aprende quais efeitos mágicos estão ativos nela.', false),
(null, 'dnd5e', 'Mãos Flamejantes', 1, 'Evocação', '1 ação', 'Pessoal (cone de 4,5m)', 'V, S', 'Instantânea', 'Uma fresta de chamas finas irrompe das pontas dos seus dedos estendidos. Cada criatura em um cone de 4,5 metros deve fazer uma salvaguarda de Destreza. Sofre 3d6 de dano de fogo se falhar, ou metade se passar.', false),
(null, 'dnd5e', 'Bruxaria', 1, 'Encantamento', '1 ação bônus', '27 metros', 'V, S, M (um olho de tritão)', 'Concentração, até 1 hora', 'Você escolhe uma criatura dentro do alcance e a amaldiçoa. Até a magia acabar, você causa 1d6 de dano necrótico extra ao alvo sempre que o atingir com um ataque. Além disso, escolha um atributo; o alvo tem desvantagem em testes de habilidade com esse atributo.', false),
(null, 'dnd5e', 'Escudo da Fé', 1, 'Abjuração', '1 ação bônus', '18 metros', 'V, S, M (um pedaço de pergaminho sagrado)', 'Concentração, até 10 minutos', 'Um campo cintilante envolve uma criatura de sua escolha dentro do alcance, concedendo-lhe um bônus de +2 na CA pela duração.', false),
(null, 'dnd5e', 'Passo Largo', 1, 'Transmutação', '1 ação', 'Toque', 'V, S, M (uma pitada de poeira)', '1 hora', 'Você toca uma criatura voluntária. O deslocamento do alvo aumenta em 3 metros até a magia acabar.', false),
(null, 'dnd5e', 'Arma Espiritual', 2, 'Evocação', '1 ação bônus', '18 metros', 'V, S', '1 minuto', 'Você cria uma arma espectral flutuante dentro do alcance. Ao conjurá-la e com uma ação bônus em turnos subsequentes, você pode mover a arma até 6 metros e atacar uma criatura a até 1,5 metro dela. Causa 1d8 + mod atributo de dano de força.', false),
(null, 'dnd5e', 'Teia', 2, 'Conjuração', '1 ação', '18 metros', 'V, S, M (um pedaço de teia de aranha)', 'Concentração, até 1 hora', 'Você cria uma rede de teias pegajosas em um cubo de 6 metros. A área é terreno difícil e concede cobertura. Criaturas que iniciarem o turno na teia ou entrarem nela devem passar numa salvaguarda de Destreza ou ficarão impedidas.', false),
(null, 'dnd5e', 'Arrombar', 2, 'Transmutação', '1 ação', '18 metros', 'V', 'Instantânea', 'Escolha um objeto que possa ser fechado (porta, baú, algemas). Um trinco mecânico ou fechadura mágica (como Tranca Arcana) é aberto ou destravado. A magia emite um som forte de batida audível a até 90 metros.', false),
(null, 'dnd5e', 'Velocidade', 3, 'Transmutação', '1 ação', '9 metros', 'V, S, M (uma lasca de alcaçuz)', 'Concentração, até 1 minuto', 'Escolha uma criatura voluntária. Até a magia acabar, o deslocamento do alvo é dobrado, ele ganha +2 de bônus na CA, vantagem em salvaguardas de Destreza e ganha uma ação adicional em cada um de seus turnos (para atacar, disparar, esquivar, esconder ou usar objeto).', false),
(null, 'dnd5e', 'Padrão Hipnótico', 3, 'Ilusão', '1 ação', '36 metros', 'S, M (um bastão de incenso incandescente)', 'Concentração, até 1 minuto', 'Você cria um padrão de cores flutuantes no ar em um cubo de 9 metros dentro do alcance. Cada criatura na área que ver o padrão deve passar em uma salvaguarda de Sabedoria ou ficará incapacitada e com deslocamento 0 (enfeitiçada/em transe) até sofrer dano ou ser acordada.', false),
(null, 'dnd5e', 'Muralha de Fogo', 4, 'Evocação', '1 ação', '36 metros', 'V, S, M (um pedaço de fósforo)', 'Concentração, até 1 minuto', 'Você cria uma muralha de fogo de até 18 metros de comprimento, 6 metros de altura e 30 centímetros de espessura, ou uma muralha circular de até 6 metros de diâmetro. Causa 5d8 de dano de fogo a criaturas que entrarem ou terminarem o turno na área.', false),
(null, 'dnd5e', 'Pele de Pedra', 4, 'Transmutação', '1 ação', 'Toque', 'V, S, M (pó de diamante no valor de 100 PO)', 'Concentração, até 1 hora', 'A pele de uma criatura voluntária que você tocar torna-se dura como rocha. Até a magia acabar, o alvo tem resistência a dano de concussão, perfuração e cortante não-mágico.', false),
(null, 'dnd5e', 'Cone de Frio', 5, 'Evocação', '1 ação', 'Pessoal (cone de 18m)', 'V, S, M (uma pequena esfera de cristal)', 'Instantânea', 'Uma rajada de ar frio irrompe de suas mãos. Cada criatura em um cone de 18 metros deve fazer uma salvaguarda de Constituição. Sofre 8d8 de dano de frio se falhar, ou metade se passar. Criaturas mortas por este dano tornam-se estátuas congeladas.', false),
(null, 'dnd5e', 'Telecinésia', 5, 'Transmutação', '1 ação', '18 metros', 'V, S', 'Concentração, até 10 minutos', 'Você ganha a habilidade de mover ou manipular criaturas ou objetos com a mente. Com sua ação, você pode mover um objeto de até 500 quilos ou tentar agarrar e mover uma criatura voluntária ou não (resolvido por testes resistidos de atributo).', false),
(null, 'dnd5e', 'Chuva de Meteoros', 9, 'Evocação', '1 ação', '1.6 quilômetros', 'V, S', 'Instantânea', 'Orbes de fogo despencam no solo em quatro pontos de sua escolha dentro do alcance. Cada criatura em uma esfera de 12 metros de raio centrada em cada ponto deve fazer uma salvaguarda de Destreza. Sofre 20d6 de dano de fogo e 20d6 de dano de concussão se falhar, ou metade se passar.', false),

-- Tormenta 20
(null, 'tormenta20', 'Luz', 0, 'Evocação', '1 ação', 'Toque', 'Nenhum', '1 dia', 'Ilumina um objeto tocado como uma tocha. Se conjurada em um objeto vestido ou carregado por uma criatura hostil, ela tem direito a um teste de Reflexos para esquivar.', false),
(null, 'tormenta20', 'Prestidigitação', 0, 'Transmutação', '1 ação', 'Curto', 'Nenhum', '1 hora', 'Realiza truques mágicos simples e inofensivos: limpa ou suja um objeto pequeno, acende uma vela, aquece comida, ou cria um som/imagem menor.', false),
(null, 'tormenta20', 'Orientação', 0, 'Adivinhação', '1 ação', 'Curto', 'Nenhum', 'Instantânea', 'Você orienta um aliado, concedendo-lhe +1 em seu próximo teste de perícia realizado até o final da cena.', false),
(null, 'tormenta20', 'Mãos Mágicas', 0, 'Transmutação', '1 ação', 'Curto', 'Nenhum', 'Sustentada', 'Cria uma mão invisível que pode erguer e mover objetos de até 5kg a até 9 metros de distância. Não pode ser usada para atacar.', false),
(null, 'tormenta20', 'Detectar Magia', 0, 'Adivinhação', '1 ação', 'Pessoal', 'Nenhum', 'Sustentada', 'Revela a presença, quantidade e intensidade de auras mágicas na área, bem como as escolas de magia a que pertencem.', false),
(null, 'tormenta20', 'Faísca', 0, 'Evocação', '1 ação', 'Curto', 'Nenhum', 'Instantânea', 'Dispara uma faísca elétrica ou de fogo que causa 1d4 de dano em um alvo. Excelente para acender fogueiras ou incomodar inimigos.', false),
(null, 'tormenta20', 'Curar Ferimentos', 1, 'Evocação', '1 ação', 'Toque', 'Nenhum', 'Instantânea', 'Cura 2d8+2 pontos de vida na criatura tocada. Mortos-vivos sofrem esse valor como dano de luz (vontade reduz à metade). +2 PM: aumenta a cura em +1d8+1.', false),
(null, 'tormenta20', 'Seta Infalível de Talude', 1, 'Evocação', '1 ação', 'Médio', 'Nenhum', 'Instantânea', 'Duas setas de energia atingem o alvo, causando 1d4+1 de dano de essência cada. Elas nunca erram. +2 PM: dispara uma seta adicional.', false),
(null, 'tormenta20', 'Armadura Arcana', 1, 'Abjuração', '1 ação', 'Pessoal', 'Nenhum', 'Cena', 'Uma barreira invisível concede +4 na Defesa. Reação (+2 PM): conjura a magia em resposta a um ataque, concedendo +6 na Defesa contra esse ataque.', false),
(null, 'tormenta20', 'Imagem Espelhada', 1, 'Ilusão', '1 ação', 'Pessoal', 'Nenhum', 'Cena', 'Cria três cópias ilusórias de si mesmo. Qualquer ataque contra você tem chance de atingir uma cópia (com 3 cópias, chance de acerto é 25%). Cada cópia destruída diminui a chance.', false),
(null, 'tormenta20', 'Escuridão', 1, 'Necromancia', '1 ação', 'Curto', 'Nenhum', 'Cena', 'Cria uma nuvem de escuridão mágica em uma área de 3m de raio. Criaturas na área recebem camuflagem leve (20% de falha).', false),
(null, 'tormenta20', 'Adaga Mental', 1, 'Encantamento', '1 ação', 'Curto', 'Mental', 'Instantânea', 'Causa 2d6 de dano mental no alvo e o deixa pasmo por 1 rodada. Vontade reduz o dano à metade e evita a condição pasmo.', false),
(null, 'tormenta20', 'Teia', 1, 'Convocação', '1 ação', 'Médio', 'Nenhum', 'Cena', 'Cria uma teia pegajosa em um cubo de 6m. Criaturas na área ficam enredadas (Reflexos evita). Sair da teia exige teste de Força ou Atletismo.', false),
(null, 'tormenta20', 'Concentração de Combate', 1, 'Adivinhação', '1 ação livre', 'Pessoal', 'Nenhum', '1 rodada', 'Você foca seus sentidos. Até o final do seu turno, sempre que realizar um teste de ataque, rola dois dados e escolhe o melhor resultado.', false),
(null, 'tormenta20', 'Bola de Fogo', 2, 'Evocação', '1 ação', 'Médio', 'Fogo', 'Instantânea', 'Uma esfera de fogo explode causando 6d6 de dano de fogo em todas as criaturas em um raio de 6m (Reflexos reduz à metade). +2 PM: aumenta o dano em +2d6.', false),
(null, 'tormenta20', 'Velocidade', 2, 'Transmutação', '1 ação', 'Curto', 'Tempo', 'Cena', 'Concede +9m de deslocamento, +2 na Defesa e Reflexos, e uma ação padrão ou de movimento extra por rodada (não cumulativo com outros efeitos de velocidade).', false),
(null, 'tormenta20', 'Invisibilidade', 2, 'Ilusão', '1 ação', 'Toque', 'Nenhum', 'Cena', 'O alvo fica invisível (+20 em testes de Furtividade). A magia termina imediatamente se o alvo realizar qualquer ação hostil (como atacar ou lançar magia nociva).', false),
(null, 'tormenta20', 'Sopro da Salvação', 2, 'Evocação', '1 reação', 'Curto', 'Nenhum', 'Instantânea', 'Você sopra uma brisa curativa que cura 1d8+1 PV em até três alvos dentro do alcance. Pode ser usada quando eles sofrem dano.', false),
(null, 'tormenta20', 'Dissipar Magia', 2, 'Abjuração', '1 ação', 'Médio', 'Nenhum', 'Instantânea', 'Cancela um efeito mágico ativo em uma criatura ou objeto, ou dissipa todas as magias em uma área de 3m de raio (exige teste de Misticismo contra CD da magia).', false),
(null, 'tormenta20', 'Voo', 2, 'Transmutação', '1 ação', 'Pessoal', 'Nenhum', 'Cena', 'Você ganha deslocamento de voo de 12 metros, permitindo pairar e se mover livremente em três dimensões.', false),
(null, 'tormenta20', 'Mente Divina', 2, 'Adivinhação', '1 ação', 'Pessoal', 'Nenhum', 'Cena', 'Seu raciocínio acelera. Você recebe +2 em testes de Inteligência e Sabedoria (e perícias baseadas nesses atributos).', false),
(null, 'tormenta20', 'Teletransporte', 3, 'Convocação', '1 ação', 'Pessoal', 'Nenhum', 'Instantânea', 'Transporta você e até quatro aliados voluntários para qualquer lugar no mesmo mundo que você conheça ou tenha visto.', false),
(null, 'tormenta20', 'Rogar Praga', 3, 'Necromancia', '1 ação', 'Curto', 'Trevas', 'Instantânea', 'Amaldiçoa o alvo com uma penalidade severa (ex: cegueira, fraqueza, mudez, ou penalidade de -5 em testes). Vontade anula.', false),
(null, 'tormenta20', 'Muralha de Fogo', 3, 'Evocação', '1 ação', 'Médio', 'Fogo', 'Cena', 'Cria uma cortina de fogo de 12m de comprimento por 3m de altura. Causa 4d6 de dano de fogo a criaturas que a atravessarem ou iniciarem o turno adjacentes.', false),
(null, 'tormenta20', 'Desintegrar', 4, 'Transmutação', '1 ação', 'Médio', 'Nenhum', 'Instantânea', 'Um raio verde causa 20d6 de dano de essência no alvo. Se os PV do alvo forem reduzidos a 0, ele vira pó cinzento. Fortitude reduz para 2d6.', false),
(null, 'tormenta20', 'Muralha de Ferro', 4, 'Convocação', '1 ação', 'Médio', 'Nenhum', 'Permanente', 'Cria uma muralha de ferro com até 12m de comprimento por 3m de altura e 5cm de espessura. Pode ser usada como barreira ou rampa.', false),
(null, 'tormenta20', 'Cólera de Azgher', 4, 'Evocação', '1 ação', 'Longo', 'Luz, Fogo', 'Instantânea', 'Um raio solar atinge uma área de 6m de raio causando 10d10 de dano de luz e fogo e cegando criaturas na área por 1d4 rodadas (Reflexos reduz dano à metade e evita cegueira).', false),
(null, 'tormenta20', 'Desejo', 5, 'Convocação', '1 ação', 'Pessoal', 'Nenhum', 'Instantânea', 'A magia mais poderosa. Pode duplicar qualquer magia de 4º círculo ou menor, curar todas as feridas, ressuscitar mortos ou criar um desejo customizado (sob custo permanente de PM ou XP).', false),
(null, 'tormenta20', 'Parar o Tempo', 5, 'Transmutação', '1 ação livre', 'Pessoal', 'Tempo', 'Instantânea', 'O tempo para para todos, exceto você. Você ganha 1d4+1 rodadas subjetivas para agir livremente. Se afetar qualquer outra criatura, o efeito termina.', false),
(null, 'tormenta20', 'Buraco Negro', 5, 'Convocação', '1 ação', 'Longo', 'Gravidade', 'Sustentada', 'Cria uma singularidade gravitacional com 9m de raio. Puxa todas as criaturas na área em direção ao centro, causando 10d6 de dano de impacto por rodada e deixando-as caídas e presas.', false),

-- Pathfinder 2e
(null, 'pathfinder', 'Arco Elétrico', 0, 'Evocação', '2 ações', '9 metros', 'V, S', 'Instantânea', 'Eletricidade salta entre dois alvos dentro do alcance. Cada criatura sofre 1d4 + mod habilidade de dano de eletricidade. Teste de Reflexos reduz à metade.', false),
(null, 'pathfinder', 'Escudo', 0, 'Abjuração', '1 ação', 'Pessoal', 'V', 'Até o início do seu próximo turno', 'Você ergue um escudo mágico que concede +1 de bônus de circunstância na CA. Você pode usar a reação de Bloqueio com Escudo para absorver até 5 de dano de um ataque, quebrando o escudo.', false),
(null, 'pathfinder', 'Produzir Chama', 0, 'Evocação', '2 ações', '18 metros ou Toque', 'V, S', 'Instantânea', 'Uma chama surge na sua mão. Faça um ataque de magia à distância ou corporal. Causa 1d4 + mod habilidade de dano de fogo. Em acertos críticos, causa 1d4 de dano de fogo persistente.', false),
(null, 'pathfinder', 'Curar', 1, 'Necromancia', '1 a 3 ações', 'Varia', 'V, S, M', 'Instantânea', 'Cura alvos vivos ou causa dano a mortos-vivos. 1 ação: Toque (1d8). 2 ações: 9 metros (1d8+8). 3 ações: emanação de 9 metros (cura todas as criaturas na área 1d8).', false),
(null, 'pathfinder', 'Mísseis Mágicos', 1, 'Evocação', '1 a 3 ações', '36 metros', 'V, S', 'Instantânea', 'Você dispara setas de força pura que nunca erram. Cada dardo causa 1d4+1 de dano de força. Cada ação gasta na conjuração dispara 1 dardo (até 3 dardos com 3 ações).', false),
(null, 'pathfinder', 'Medo', 1, 'Encantamento', '2 ações', '9 metros', 'V, S', 'Varia', 'Infunde pavor em uma criatura. Baseado no teste de Vontade do alvo, ele fica Assustado 1 (sucesso), Assustado 2 e Fugindo por 1 rodada (falha), ou Assustado 3 e Fugindo por 1 rodada (falha crítica).', false),
(null, 'pathfinder', 'Dissipar Magia', 2, 'Abjuração', '2 ações', '36 metros', 'V, S', 'Instantânea', 'Você tenta neutralizar um efeito mágico ativo ou uma magia em progresso. Faça um teste de neutralização contra a CD do efeito mágico.', false),
(null, 'pathfinder', 'Imagem Espelhada', 2, 'Ilusão', '2 ações', 'Pessoal', 'V, S', '1 minuto', 'Cria três duplicatas ilusórias que imitam seus movimentos. Inimigos atacando você podem errar e destruir uma duplicata em vez de atingi-lo.', false),
(null, 'pathfinder', 'Bola de Fogo', 3, 'Evocação', '2 ações', '150 metros', 'V, S', 'Instantânea', 'Uma explosão de fogo em uma área de 6 metros de raio causa 6d6 de dano de fogo. Alvos realizam teste de Reflexos para reduzir o dano.', false),
(null, 'pathfinder', 'Velocidade', 3, 'Transmutação', '2 ações', '9 metros', 'V, S', 'Concentração, até 1 minuto', 'Concede aceleração ao alvo. O alvo ganha 1 ação extra em cada um de seus turnos, que só pode ser usada para dar um Passo, Disparar ou Atacar.', false),
(null, 'pathfinder', 'Porta Dimensional', 4, 'Conjuração', '2 ações', '36 metros', 'V, S', 'Instantânea', 'Você se teletransporta instantaneamente para um local desocupado dentro do alcance que você possa ver.', false),
(null, 'pathfinder', 'Cone de Frio', 5, 'Evocação', '2 ações', 'Pessoal (cone de 18m)', 'V, S', 'Instantânea', 'Uma rajada de gelo e frio causa 12d6 de dano de frio em todas as criaturas na área do cone de 18 metros. Teste de Reflexos reduz à metade.', false),
(null, 'pathfinder', 'Desintegrar', 6, 'Transmutação', '2 ações', '36 metros', 'V, S', 'Instantânea', 'Um raio verde causa 12d10 de dano de força (Fortitude reduz). Se o alvo for reduzido a 0 pontos de vida por este dano, ele é totalmente desintegrado em pó.', false),
(null, 'pathfinder', 'Labirinto', 8, 'Conjuração', '2 ações', '9 metros', 'V, S', 'Sustentada, até 1 minuto', 'Você aprisiona o alvo em um labirinto extradimensional sem salvaguarda. O alvo deve usar ações de Sobrevivência ou Inteligência para tentar escapar.', false),
(null, 'pathfinder', 'Desejo', 10, 'Conjuração', '3 ações', 'Pessoal', 'V, S, M', 'Instantânea', 'Altera a realidade para duplicar quase qualquer outra magia de nível 9 ou inferior, ou realiza um desejo customizado sob julgamento do narrador.', false);
